async function api(path,body?:any){const r=await fetch('/api/'+path,{credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},method:body?'POST':'GET',body:body?JSON.stringify(body):undefined});const result=await r.json();if(!r.ok){const e:any=new Error(result.error||'회선 연결을 확인하세요.');e.status=r.status;throw e;}return result;}
function Brand(){return <span className="brand"><span className="brand-mark" aria-hidden="true">Ⅱ</span><span>아임 낫 어 휴먼 <b>2</b><small>소거 위원회</small></span></span>;}
function TitleLogo(){return <div className="title-logo"><img src={titleLogo} alt="THE LAST VOTE" /></div>;}
function CouncilAvatar({member}:any){const portrait=member&&councilPortraits[member.id];return portrait?<span className="sigil council-avatar"><img src={portrait} alt=""/></span>:<span className="sigil">{member?.sigil||'·'}</span>; }
function SuspicionStrip({member,active=false}:any){if(!member)return null;return <div className={'battle-suspicion-mini'+(active?' active':'')} role="meter" aria-label={`${member.name} 의심도`} aria-valuenow={member.suspicion} aria-valuemin={0} aria-valuemax={100}><span><i style={{width:`${member.suspicion}%`}}/></span>{active&&<b>{member.suspicion}</b>}</div>;}

function LobbyScreen({user,game,catalog,mask,setMask,daily,scenario,setScenario,busy,onChooseLocation,onContinue,onViewPrevious}:any){
 const [detailRole,setDetailRole]=useState<any>(null);
 const locked=(m:any)=>user.role==='demo'?m.id!=='scribe':m.unlock>user.profile.runs||daily&&m.id!=='scribe';
 const detailLocked=detailRole?locked(detailRole):false;
 return <main id="main" className="lobby role-select-lobby">
  <header className="role-select-header"><h1>직업 선택</h1></header>
  <section className="role-card-grid" aria-label="직업 선택">
   {(catalog?.masks||[]).map((m:any)=>{const isLocked=locked(m);return <button type="button" key={m.id} className={'role-card'+(mask===m.id?' selected':'')+(isLocked?' locked':'')} aria-disabled={isLocked} aria-pressed={mask===m.id} aria-label={`${m.name} 상세 정보 보기`} onClick={()=>setDetailRole(m)}>
    <span className={`role-art-placeholder role-art-${m.id}`} style={{backgroundImage:`url(${roleArtSheet})`}} aria-hidden="true"/>
    {mask===m.id&&<span className="role-card-selected-stamp">선택됨</span>}
    {isLocked&&<span className="role-card-lock-overlay"><span className="role-card-lock-badge"><LockKey size={16}/>잠김</span></span>}
    <span className="role-card-body"><b className="role-card-name">{m.name}</b></span>
    {mask===m.id&&<Check className="role-card-check" size={20}/>}
   </button>;})}
  </section>
  <div className="role-select-actions">
   {user.role==='demo'&&<label className="role-scenario"><span>시연 구성</span><select value={scenario} onChange={e=>setScenario(+e.target.value)}><option value="0">발전소</option><option value="1">폐역</option></select></label>}
   <div className="role-actions"><button className="button primary role-start" disabled={busy} onClick={game&&game.phase!=='ended'?onContinue:onChooseLocation}>{busy?'회선 배정 중…':game&&game.phase!=='ended'?'잠입 이어하기':'잠입 시작'}<ArrowRight size={18}/></button>{game?.phase==='ended'&&<button className="text-button role-previous" onClick={onViewPrevious}>지난 잠입 보기<ArrowUpRight size={16}/></button>}</div>
  </div>
  {detailRole&&<Modal title={detailRole.name} className="role-dossier-modal" onClose={()=>setDetailRole(null)}><div className="role-detail"><div className={`role-detail-art role-art-${detailRole.id}`} style={{backgroundImage:`url(${roleArtSheet})`}} aria-hidden="true"/><div className="role-detail-copy"><div className="role-story-block"><span className="mono role-detail-label">과거</span><p className="role-detail-story">{detailRole.story}</p></div><div className="role-ability-block"><span className="mono role-detail-label">능력</span><p>{detailRole.desc}</p></div>{detailLocked?<p className="role-detail-lock"><LockKey size={15}/>{user.role==='demo'?'일반 계정에서 해금':`${detailRole.unlock}판 완료 후 해금`}</p>:<button className="button primary full" onClick={()=>{setMask(detailRole.id);setDetailRole(null);}}>이 직업으로 선택<Check size={18}/></button>}</div></div></Modal>}
 </main>;
}

