 useEffect(()=>{if(game){setZone(game.missionZone||game.proposedZone||game.radioZone);setDrafts(null);setSpeech('');setBattleChatExpanded(true);}},[game?.day,game?.id]);useEffect(()=>{if(game?.phase==='operation')setOperationPlan('wait');},[game?.id,game?.day,game?.phase]);
 useEffect(()=>{const key=game?.id?`${game.id}:${game.day}`:'';if(game?.phase==='discussion'&&key&&incidentBriefingSeen.current!==key){setIncidentBriefingClosing(false);setIncidentReveal(false);setOpeningPending(false);setIncidentBriefingOpen(true);}else if(game?.phase!=='discussion'){setIncidentBriefingOpen(false);setIncidentBriefingClosing(false);setIncidentReveal(false);setOpeningPending(false);}},[game?.id,game?.day,game?.phase]);
