 async function work(fn:any){if(busy)return;setBusy(true);setError('');try{await fn();return true;}catch(e:any){setError(e.message);if(e.status===401){setUser(null);setScreen('landing');}if(e.status===409&&user){const r=await api('game');setGame(r.game);}return false;}finally{setBusy(false);}}
 async function action(kind:string,extra:any={}){return work(async()=>{const r=await api('game/action',{action:kind,version:game.version,...extra});setGame(r.game);setAi(r.ai);if(r.user)setUser(r.user);if(r.drafts)setDrafts(r.drafts);if(kind==='talk'){setSpeech('');setSpeechOpen(false);setDrafts(null);}if(kind==='begin')setScreen('game');if(kind==='reward'&&r.game.phase==='report')setScreen('locations');});}
