 const battleCardImages:Record<string,string>={noise:tarotMoon,discord:tarotFiveWands,budget:tarotFourPentacles,forge:tarotSevenSwords,proxy:tarotMagician,radio:tarotStar,gaze:tarotHighPriestess,read:tarotJustice,sensor:tarotSevenCups,revive:tarotJudgement,silence:tarotHermit,decoy:tarotChariot};
