    <div className="battle-round-heading"><div><span className="mono">현장 훈련 · DAY {String(game.day).padStart(2,'0')}</span><h2>위원회 작전 회의</h2></div><b className="battle-turn-count">발언 {game.turns} / 2</b></div>
